// Shared helpers for the DSP*/Timing* tests: golden-fixture loading
// (generated by scripts/native/fixtures-dsp.ts) and small signal utilities.

import Foundation
import XCTest
@testable import LumberCore

enum DSPTestSupport {
    /// Fixtures/<rel> parsed as JSON.
    static func fixture(_ rel: String, file: StaticString = #filePath, line: UInt = #line) throws -> [String: Any] {
        guard let base = Bundle.module.resourceURL else { throw XCTSkip("no resource bundle") }
        let url = base.appendingPathComponent("Fixtures").appendingPathComponent(rel)
        let data = try Data(contentsOf: url)
        guard let obj = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            XCTFail("fixture \(rel) is not an object", file: file, line: line)
            return [:]
        }
        return obj
    }

    /// `{"f32": base64}` → [Float].
    static func f32(_ v: Any?) -> [Float] {
        guard let d = v as? [String: Any], let s = d["f32"] as? String, let data = Data(base64Encoded: s) else {
            preconditionFailure("not an f32 blob: \(String(describing: v))")
        }
        return data.withUnsafeBytes { raw in
            (0..<(data.count / 4)).map { Float(bitPattern: raw.loadUnaligned(fromByteOffset: $0 * 4, as: UInt32.self).littleEndian) }
        }
    }

    /// `{"u8": base64}` → [UInt8].
    static func u8(_ v: Any?) -> [UInt8] {
        guard let d = v as? [String: Any], let s = d["u8"] as? String, let data = Data(base64Encoded: s) else {
            preconditionFailure("not a u8 blob")
        }
        return [UInt8](data)
    }

    static func chans(_ v: Any?) -> [[Float]] { (v as! [Any]).map { f32($0) } }

    static func num(_ v: Any?) -> Double {
        if let d = v as? Double { return d }
        if let n = v as? NSNumber { return n.doubleValue }
        if let s = v as? String, s == "NaN" { return .nan }
        preconditionFailure("not a number: \(String(describing: v))")
    }

    static func nums(_ v: Any?) -> [Double] { (v as! [Any]).map { num($0) } }

    static func dict(_ v: Any?) -> [String: Any] { v as! [String: Any] }
    static func list(_ v: Any?) -> [[String: Any]] { v as! [[String: Any]] }

    /// Max |a − b| (∞ on a length mismatch).
    static func maxErr(_ a: [Float], _ b: [Float]) -> Double {
        guard a.count == b.count else { return .infinity }
        var e = 0.0
        for i in 0..<a.count {
            let d = abs(Double(a[i]) - Double(b[i]))
            if d.isNaN { return .infinity }
            e = max(e, d)
        }
        return e
    }

    static func maxErr(_ a: [[Float]], _ b: [[Float]]) -> Double {
        guard a.count == b.count else { return .infinity }
        return zip(a, b).map { maxErr($0, $1) }.max() ?? 0
    }

    /// Fail if channels differ by more than `tol` (absolute).
    static func assertClose(_ got: [[Float]], _ want: [[Float]], tol: Double, _ msg: String,
                            file: StaticString = #filePath, line: UInt = #line) {
        let e = maxErr(got, want)
        if ProcessInfo.processInfo.environment["LUMBER_REPORT_ERR"] != nil { print("maxerr \(msg): \(e)") }
        XCTAssertLessThanOrEqual(e, tol, "\(msg): maxerr \(e)", file: file, line: line)
    }

    /// Equal within 1e-12 relative. Foundation's JSON parser on Linux can be a
    /// last-ulp off from the shortest-round-trip numbers JSON.stringify writes.
    static func near(_ a: Double?, _ b: Double, _ msg: String = "", file: StaticString = #filePath, line: UInt = #line) {
        guard let a else { return XCTFail("nil, want \(b) \(msg)", file: file, line: line) }
        XCTAssertEqual(a, b, accuracy: 1e-12 * max(1, abs(b)), msg, file: file, line: line)
    }

    static func near(_ a: [Double], _ b: [Double], _ msg: String = "", file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertEqual(a.count, b.count, msg, file: file, line: line)
        for (x, y) in zip(a, b) { near(x, y, msg, file: file, line: line) }
    }

    static func tone(_ freq: Double, _ amp: Double, _ n: Int, _ sr: Double) -> [Float] {
        (0..<n).map { Float(amp * sin(2 * Double.pi * freq * Double($0) / sr)) }
    }

    static func peak(_ x: [Float]) -> Float { x.reduce(0) { max($0, abs($1)) } }
    static func finite(_ x: [Float]) -> Bool { x.allSatisfy { $0.isFinite } }

    /// The seeded LCG from tests/calibration.test.ts.
    struct TestRNG {
        var s: UInt32
        init(_ seed: UInt32) { s = seed }
        mutating func next() -> Double {
            s = s &* 1664525 &+ 1013904223
            return Double(s) / 4294967296.0
        }
    }
}
